styles:
.b-press-articles { margin: 2em 0; }
.b-press-articles__title { margin: 0 0 1em; font-size: 1.5em; }
.b-press-articles__list { display: grid; grid-template-columns: repeat(auto-fill, minmax(16em, 1fr)); gap: 1.5em; margin: 0; padding: 0; list-style: none; }
.b-press-articles__item { display: flex; flex-direction: column; gap: 0.5em; }
.b-press-articles__outlet { display: flex; min-height: 2em; align-items: center; font-weight: 600; font-size: 0.85em; }
.b-press-articles__logo { display: block; max-width: 8em; max-height: 2em; width: auto; height: auto; }
.b-press-articles__link { color: inherit; font-size: 1.1em; font-weight: 600; }
.b-press-articles__meta, .b-press-articles__excerpt { margin: 0; font-size: 0.9em; opacity: 0.8; }
.b-press-articles__pdf { align-self: flex-start; font-size: 0.85em; color: inherit; }
